import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { fetchNews } from "../services/api";
import "../styles/news.css";

export default function NewsList() {
  const [articles, setArticles] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [sourceFilter, setSourceFilter] = useState("all");

  const loadArticles = async (pageNum = 1, append = false) => {
    try {
      if (pageNum === 1) setLoading(true);
      setError(null);

      const data = await fetchNews({ page: pageNum, limit: 12 });
      let filtered = data.articles || [];

      if (sourceFilter !== "all") {
        filtered = filtered.filter(a => a.source?.toLowerCase().includes(sourceFilter.toLowerCase()));
      }

      if (append) {
        setArticles(prev => [...prev, ...filtered]);
      } else {
        setArticles(filtered);
      }

      setHasMore(filtered.length > 0);
    } catch (err) {
      setError("Không thể tải tin tức. Vui lòng thử lại sau.");
      console.error("Lỗi:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadArticles(1, false);
  }, [sourceFilter]);

  const handleLoadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    loadArticles(nextPage, true);
  };

  return (
    <div className="news-page">
      {/* 🌆 Hero Banner */}
      <section className="news-hero">
        <div className="hero-overlay">
          <h1>Tin tức Bất Động Sản</h1>
          <p>Cập nhật xu hướng thị trường và phân tích chuyên sâu từ các nguồn uy tín</p>
        </div>
      </section>

      {/* 🧭 Filter Bar */}
      <div className="news-filter container">
        {["all", "vnexpress", "cafef", "savills"].map((src) => (
          <button
            key={src}
            className={`filter-btn ${sourceFilter === src ? "active" : ""}`}
            onClick={() => setSourceFilter(src)}
          >
            {src === "all" ? "Tất cả" : src.charAt(0).toUpperCase() + src.slice(1)}
          </button>
        ))}
      </div>

      <div className="container">
        {error ? (
          <div className="news-error"><p>{error}</p></div>
        ) : loading && articles.length === 0 ? (
          <div className="news-loading">Đang tải tin tức...</div>
        ) : (
          <>
            <div className="news-grid">
              {articles.map((article, index) => (
                <Link
                  to={`/news/${article.id}`}
                  key={article.id}
                  className="news-card fade-in"
                  style={{ animationDelay: `${index * 0.05}s` }}
                >
                  <div
                    className="news-thumb"
                    style={{ backgroundImage: `url(${article.thumbnail || "/placeholder-news.jpg"})` }}
                  >
                    <div className="thumb-overlay"></div>
                    <span className="news-source-tag">{article.source}</span>
                  </div>
                  <div className="news-info">
                    <h3 className="news-title">{article.title}</h3>
                    <p className="news-meta">
                      {article.publishedAt ? new Date(article.publishedAt).toLocaleDateString("vi-VN") : "Chưa rõ ngày"}
                    </p>
                    <p className="news-excerpt">{article.excerpt || "Xem chi tiết..."}</p>
                  </div>
                </Link>
              ))}
            </div>

            {hasMore && (
              <div className="load-more">
                <button onClick={handleLoadMore} disabled={loading} className="load-more-btn">
                  {loading ? "Đang tải..." : "Xem thêm tin"}
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}
